template <class T, size_t N>  // N must be a power of two
class Spsc {
  static_assert(N && (N & (N - 1)) == 0);
  alignas(64) std::atomic<size_t> head_{0};  // written by producer only
  alignas(64) std::atomic<size_t> tail_{0};  // written by consumer only
  alignas(64) T buf_[N];
public:
  bool push(const T& v) {
    size_t h = head_.load(std::memory_order_relaxed);
    if (h - tail_.load(std::memory_order_acquire) == N) return false;  // full
    buf_[h & (N - 1)] = v;
    head_.store(h + 1, std::memory_order_release);  // publish the slot
    return true;
  }
  bool pop(T& out) {
    size_t t = tail_.load(std::memory_order_relaxed);
    if (head_.load(std::memory_order_acquire) == t) return false;  // empty
    out = buf_[t & (N - 1)];
    tail_.store(t + 1, std::memory_order_release);  // free the slot
    return true;
  }
};

